(1266, 'REQUIREMENTS_CALCULATION_TR', '<table cellpadding="3" cellspacing="0" border="1" width="100%">\r\n        <tr>\r\n           <th>Kolonas dati</th>\r\n           <th>Obligāts</th>\r\n           <th>Kolonas datu apraksts</th>\r\n        </tr>\r\n        <tr>\r\n            <td>Grupas kods</td>\r\n            <td>+</td>\r\n            <td>Kalkulācijas grupas kods. Var saturēt tikai sekojošus simbolus `a`-`z`, `A`-`Z`, `0`-`9`. Maksimāli 5 simboli. </td>\r\n        </tr>\r\n        <tr>\r\n            <td>Kalkulācijas šifrs</td>\r\n            <td>+</td>\r\n            <td>Kalkulācijas šifrs. Var saturēt tikai sekojošus simbolus `0`-`9`. Maksimāli 5 simboli.</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Kalkulācijas nosaukums</td>\r\n            <td>+</td>\r\n            <td>Kalkulācijas nosaukums. Maksimāli 150 simboli.</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Mērvienība</td>\r\n            <td>+</td>\r\n            <td>Kalkulācijas mērvienība. Maksimāli 15 simboli. </td>\r\n        </tr>\r\n\r\n        <tr>\r\n            <td>Fiziskais rādītājs</td>\r\n            <td>+</td>\r\n            <td>Fiziska rādītāja pazime. Var saturēt tikai sekojošus simbolus [`1`-`9`]`z` vai [`1`-`11`]`v`. Maksimāli 3 simboli. </td>\r\n        </tr>\r\n       	<tr>\r\n            <td>Darbuzņēmējs</td>\r\n            <td>+</td>\r\n            <td>Darbuzņēmēja identifikators. Cipars.</td>\r\n        </tr>\r\n	<tr>\r\n            <td>ED nodaļa</td>\r\n            <td>+</td>\r\n            <td>ED nodaļas nosaukums. Maksimāli 250 simboli. </td>\r\n        </tr>\r\n	<tr>\r\n            <td>Plāna cena</td>\r\n            <td>+</td>\r\n            <td>Plāna darbu cena. Cipars formatā [xxxxx.xx]. </td>\r\n        </tr>\r\n	<tr>\r\n            <td>Neplāna cena</td>\r\n            <td>+</td>\r\n            <td>Neplāna darbu cena. Cipars formatā [xxxxx.xx]. </td>\r\n        </tr>\r\n<tr>\r\n            <td>Stihijas kalkul.</td>\r\n            <td>+</td>\r\n            <td>Stihijas kalkul. Cipars formatā  [0/1]</td>\r\n        </tr>\r\n      <tr>\r\n            <td>Apraksts</td>\r\n            <td>-</td>\r\n            <td>Kalkulācijas apraksts. Maksimāli 2000 simboli. </td>\r\n        </tr>\r\n       </table>'),
(1267, 'REQUIREMENTS_HARMONIZED', '<table cellpadding="3" cellspacing="0" border="1" width="100%">\n        <tr>\n           <th>Kolonas dati</th>\n           <th>Obligāts</th>\n           <th>Kolonas datu apraksts</th>\n        </tr>\n        <tr>\n            <td>ĢIS iecirkņa Nr.</td>\n            <td>+</td>\n            <td>ED iecirkņa Nr. Var saturēt tikai sekojošus simbolus `0`-`9`. Maksimāli 5 simboli. </td>\n        </tr>\n        <tr>\n            <td>Vārds</td>\n            <td>+</td>\n            <td>Saskaņotaja vārds. Maksimāli 30 simboli.</td>\n        </tr>\n        <tr>\n            <td>Uzvārds</td>\n            <td>+</td>\n            <td>Saskaņotaja uzvārds. Maksimāli 30 simboli.</td>\n        </tr>\n        <tr>\n            <td>Amats</td>\n            <td>+</td>\n            <td>Saskaņotaja amats. Maksimāli 50 simboli. </td>\n        </tr>\n        <tr>\n            <td>Struktūrvienība</td>\n            <td>+</td>\n            <td>Nodaļas nosaukums. Maksimāli 250 simboli. </td>\n        </tr>\n       </table>'),
