INSERT INTO `KL_KALKULACIJA_TRASE` (`KKAL_ID`, `KKAL_GRUPAS_KODS`, `KKAL_SHIFRS`, `KKAL_NOSAUKUMS`, `KKAL_APRAKSTS`, `KKAL_MERVIENIBA`, `KKAL_IR_AKTIVS`, `KKAL_FIZ_RADIJUMS`, `KKAL_KEDI_SECTION`, `KKAL_KWOI_KODS`, `KKAL_PLAN_PRICE`, `KKAL_NOT_PLAN_PRICE`, `KKAL_IS_ELEMENT`, `KKAL_KOEFICENT`) VALUES
(1, '55', '5501', 'Trases attīrīšana ar rokām ar zaru utilizāciju', '<><><><><>EPL trases horizontālā trašu tīrīšana un/vai vertikālā zaru apzāģēšana („koridora” prasības) atbilstoši kvalitātes prasībām un 100% zaru utilizāciju.\nNebojāt kokmateriālu kvalitāti un nozāģētos kokus atzaro un atstāj nesagarumotus, ja meža īpašnieks nav norādījis savādāk atbilstoši normatīvo dokumentu noteiktajai kārtībai.\nNozāģētos kokus novietot EPL trases pēdējā metrā (gar malu) vai meža īpašnieka norādītajā vietā atbilstoši normatīvo dokumentu noteiktajai kārtībai.\nVisiem nozāģētajiem kokiem, kas krūšu augstumā ir diametrā virs 12 cm, jābūt kvalitatīvi atzarotiem līdz ar stumbru. Atzarojot kokus, nedrīkst atstāt garus zaru stumbeņus pie stumbra.\nUzdotajam apaugumam jābūt nozāģētam tā, lai krūmu/koku celmi nebūtu augstāki par 10 cm', 'ha', 1, '1z', 'Aizkraukle', '45403013648', 10000.00, 200.00, 0, 1.00),
(2, '55', '5502', 'Trases attīrīšana ar rokām bez zaru utilizācijas', 'EPL trases horizontālā trašu tīrīšana un/vai vertikālā zaru apzāģēšana („koridora” prasības) atbilstoši kvalitātes prasībām.\nNebojāt kokmateriālu kvalitāti un nozāģētos kokus atzaro un atstāj nesagarumotus, ja meža īpašnieks nav norādījis savādāk atbilstoši normatīvo dokumentu noteiktajai kārtībai.\nNozāģētos kokus novietot EPL trases pēdējā metrā (gar malu) vai meža īpašnieka norādītajā vietā atbilstoši normatīvo dokumentu noteiktajai kārtībai.\nVisiem nozāģētajiem kokiem, kas krūšu augstumā ir diametrā virs 12 cm, jābūt kvalitatīvi atzarotiem līdz ar stumbru. Atzarojot kokus, nedrīkst atstāt garus zaru stumbeņus pie stumbra.\nNozāģētie koki nedrīkst atrasties zem zaru kaudzēm. Atzarotiem zariem, kas ir garumā virs 2 metriem, jābūt pārzāģētiem uz pusēm. Koka galotnes arī jāsazāģē sīkāk, lai neveidotos lielās zaru kaudzes un nesakārtotas trases iespaids. Zarus nedrīkst atstāt ceļmalās grāvjos, meliorācijas grāvjos.\nNozāģētos zarus un/vai krūmus novietot EPL trases pēdējā metrā (gar malu) vai izklaidus zem līnijas. Uzdotajam apaugumam jābūt nozāģētam tā, lai krūmu/koku celmi nebūtu augstāki par 10 cm', 'ha', 1, '2z', 'Aizkraukle', '45403013648', 110.00, 210.00, 0, 1.00),
(3, '55', '5503', 'Trases attīrīšana ar rokām bez vertikālās zaru apzāģēšanas ar zaru utilizāciju', '--', 'ha', 1, '3z', 'Aizkraukle', '45403013648', 120.00, 220.00, 0, 1.00),
(4, '55', '5504', 'Trases attīrīšana ar rokām bez vertikālās zaru apzāģēšanas bez zaru utilizācijas', '--', 'ha', 1, '4z', 'Aizkraukle', '45403013648', 130.00, 230.00, 0, 1.00),
(5, '55', '5505', 'Koku zāģēšana', '--', 'm3', 1, '5z', 'Aizkraukle', '45403013648', 140.00, 240.00, 0, 1.00),
